actions.inlineCode:
if (!window.deck) {
    window.deck = ['Strike', 'Strike', 'Defend', 'Defend', 'Draw2'];
    window.hand = [];
}
let amount = 3;
for (let i = 0; i < amount; i++) {
    if (window.deck.length > 0) {
        let card = window.deck.pop();
        window.hand.push(card);
        let newCard = runtimeScene.createObject('CardObject');
        if(newCard) {
            newCard.setPosition(100 + (window.hand.length * 90), 450);
            newCard.getVariables().get('CardName').setString(card);
        }
    }
}
